import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { getMyListings, deleteListing } from '../../services/carListingService';
import toast from 'react-hot-toast';

const CustomerDashboard = () => {
  const [listings, setListings] = useState([]);
  const [loading, setLoading] = useState(true);

  const fetchListings = async () => {
    try {
      const data = await getMyListings();
      setListings(data);
    } catch (err) {
      toast.error('Không thể tải danh sách xe');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchListings();
  }, []);

  const handleDelete = async (id) => {
    if (window.confirm('Bạn có chắc muốn xóa yêu cầu này?')) {
      try {
        await deleteListing(id);
        toast.success('Đã xóa yêu cầu');
        fetchListings();
      } catch (err) {
        toast.error(err.response?.data?.message || 'Xóa thất bại');
      }
    }
  };

  const getStatusBadge = (status) => {
    const statusMap = {
      pending: 'bg-yellow-100 text-yellow-800',
      priced: 'bg-blue-100 text-blue-800',
      accepted: 'bg-green-100 text-green-800',
      rejected: 'bg-red-100 text-red-800',
    };
    const textMap = {
      pending: 'Chờ xử lý',
      priced: 'Đã định giá',
      accepted: 'Đã chấp thuận',
      rejected: 'Từ chối',
    };
    return (
      <span className={`px-2 py-1 rounded text-xs font-semibold ${statusMap[status]}`}>
        {textMap[status]}
      </span>
    );
  };

  if (loading) return <div className="text-center p-8">Đang tải...</div>;

  return (
    <div className="container mx-auto p-6">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold">Xe của tôi</h2>
        <Link
          to="/customer/new-listing"
          className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
        >
          + Đăng bán xe
        </Link>
      </div>

      {listings.length === 0 ? (
        <div className="text-center p-10 bg-gray-50 rounded">
          <p className="text-gray-500">Bạn chưa đăng bán xe nào.</p>
          <Link to="/customer/new-listing" className="text-blue-600 underline mt-2 inline-block">
            Đăng bán ngay
          </Link>
        </div>
      ) : (
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {listings.map((listing) => (
            <div key={listing._id} className="border rounded-lg p-4 shadow-sm hover:shadow-md transition">
              <div className="flex justify-between items-start">
                <div>
                  <h3 className="text-xl font-semibold">
                    {listing.brand} {listing.model}
                  </h3>
                  <p className="text-gray-600">{listing.year} - {listing.mileage.toLocaleString()} km</p>
                </div>
                {getStatusBadge(listing.status)}
              </div>
              <div className="mt-3">
                <p><strong>Giá mong muốn:</strong> {listing.desiredPrice.toLocaleString()} VND</p>
                {listing.suggestedPrice && (
                  <p className="text-green-600">
                    <strong>Giá đề xuất:</strong> {listing.suggestedPrice.toLocaleString()} VND
                  </p>
                )}
              </div>
              <div className="mt-4 flex space-x-2">
                <Link
                  to={`/customer/listing/${listing._id}`}
                  className="text-blue-600 hover:underline text-sm"
                >
                  Chi tiết
                </Link>
                {listing.status === 'pending' && (
                  <>
                    <Link
                      to={`/customer/edit-listing/${listing._id}`}
                      className="text-yellow-600 hover:underline text-sm"
                    >
                      Sửa
                    </Link>
                    <button
                      onClick={() => handleDelete(listing._id)}
                      className="text-red-600 hover:underline text-sm"
                    >
                      Xóa
                    </button>
                  </>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default CustomerDashboard;
